from .ranges import RangeError, bounds


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data
    try:
        start, end = bounds(range_header, length)
    except RangeError:
        return (416,
                {'Content-Length': '0', 'Content-Range': 'bytes */%d' % length},
                b'')
    body = data[start:end + 1]
    return (206,
            {'Content-Length': str(len(body)),
             'Content-Range': 'bytes %d-%d/%d' % (start, end, length)},
            body)
